<?php
$productTabs = ['hpp'=>!empty($storeProductMode)?'Harga Pokok Produk':'Harga Pokok Penjualan Global','harga'=>'Harga & Diskon','stok'=>!empty($storeProductMode)?'Inventori & Stok':'Stok'];
$priceText = static function (array $variants, string $field): string {
    $values = array_values(array_filter(array_column($variants,$field), static fn($v) => $v !== null));
    if (!$values) return 'Belum tersedia';
    return min($values) == max($values) ? formatRp(min($values)) : formatRp(min($values)) . ' – ' . formatRp(max($values));
};
$soldLabel = $globalFilters['date_start'] || $globalFilters['date_end'] ? 'Terjual (periode)' : 'Terjual (14 Hari)';
?>
<section class="space-y-4"><div class="flex justify-end"><button type="button" data-open-hpp-editor class="rounded-xl bg-brand-600 text-white px-4 py-2.5 text-xs font-bold">▦ Atur HPP</button></div>
    <div class="grid grid-cols-2 lg:grid-cols-4 gap-3"><?php foreach (['Total Produk'=>count($catalogData['products']),$soldLabel=>$catalogData['sold'],'Produk dengan HPP'=>count($catalogData['products'])-$catalogData['missing_hpp'],'Toko dalam hasil'=>count(array_unique(array_column($catalogData['products'],'store_id')))] as $label=>$value): ?><div class="rounded-2xl border bg-white p-5"><p class="font-extrabold text-xl"><?= number_format((float)$value,0,',','.') ?></p><p class="text-xs text-slate-500 mt-2"><?= $label ?></p></div><?php endforeach; ?></div>
    <?php if ($catalogData['missing_hpp']): ?><div class="rounded-xl border border-amber-200 bg-amber-50 text-amber-800 px-4 py-3 text-xs"><?= $catalogData['missing_hpp'] ?> produk belum memiliki HPP lengkap. Klik pensil pada HPP produk atau buka varian untuk mengatur HPP.</div><?php endif; ?>
    <div class="bg-white rounded-2xl border border-slate-200 overflow-hidden">
        <nav class="flex flex-wrap gap-1 p-2 bg-slate-50 border-b" aria-label="Menu produk"><?php foreach ($productTabs as $key=>$title): ?><a href="?<?= $query(['product_section'=>$key]) ?>" <?= $productSection === $key ? 'aria-current="page"' : '' ?> class="px-4 py-2 rounded-lg text-xs <?= $productSection === $key ? 'bg-white shadow-sm font-bold text-slate-900' : 'text-slate-500' ?>"><?= $title ?></a><?php endforeach; ?></nav>
        <p class="p-4 text-[11px] text-slate-500 border-b"><?= !empty($storeProductMode)?'Produk, varian, harga, stok, dan status berasal dari katalog API toko yang dipilih.':'Harga, diskon, stok, dan status terkini mengikuti katalog resmi yang tersimpan. Baris bertanda “Data transaksi” menampilkan harga transaksi terakhir; stok/status belum tersedia hingga katalog tersinkron.' ?> HPP yang disimpan memperbarui transaksi terkait. Gunakan ikon tanggal jika HPP hanya berlaku sejak tanggal tertentu.</p>
        <div class="overflow-auto max-h-[750px]"><table class="w-full text-xs whitespace-nowrap jl-table"><thead class="bg-slate-50 text-slate-500 uppercase text-[10px]"><tr><?php foreach (['Produk','SKU','Platform',$soldLabel,'Harga','HPP Produk', $productSection === 'stok' ? 'Stok' : 'Varian','Status'] as $title): ?><th class="p-3 text-left"><?= $title ?></th><?php endforeach; ?></tr></thead><tbody>
        <?php foreach ($catalogData['products'] as $index=>$product): $variants=$product['variants']; $first=$variants[0]; $statuses=array_unique(array_map(static fn($v)=>$v['source_status'] ?: 'Belum tersedia',$variants)); ?>
            <tr class="border-t hover:bg-slate-50"><td class="p-3"><button type="button" class="text-left flex items-center gap-3" data-product-toggle="product-<?= $index ?>" aria-expanded="false"><span aria-hidden="true">⌄</span><?php if (preg_match('~^https?://~i',$first['image_url'] ?? '')): ?><img src="<?= htmlspecialchars($first['image_url']) ?>" alt="" loading="lazy" class="w-10 h-10 rounded-lg object-cover"><?php endif; ?><span class="max-w-[420px] whitespace-normal"><b><?= htmlspecialchars($product['name']) ?></b><span class="block text-[10px] text-slate-400 mt-1"><?= htmlspecialchars($product['store_name']) ?><?= !empty($first['observed']) ? ' · Data transaksi / mapping' : '' ?></span></span></button></td><td class="p-3"><?= htmlspecialchars($product['sku'] ?: (count($variants) === 1 ? $first['sku'] : 'Beberapa SKU')) ?></td><td class="p-3"><?= htmlspecialchars($product['platform']) ?></td><td class="p-3"><?= $product['sold'] ?></td><td class="p-3"><?= $priceText($variants,'price') ?><?php if (empty($first['observed']) && !empty($first['external_product_id'])): ?><button type="button" data-edit-marketplace-price data-store="<?= htmlspecialchars($product['store_id']) ?>" data-product="<?= htmlspecialchars($first['external_product_id']) ?>" class="p-2 text-slate-500 hover:text-orange-600" aria-label="Edit harga produk"><svg aria-hidden="true" viewBox="0 0 24 24" width="15" height="15" class="inline-block align-middle" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="m16 4 4 4M4 16 16 4a2.83 2.83 0 0 1 4 4L8 20l-5 1 1-5Z"/></svg></button><?php endif; ?></td><td class="p-3"><?= $priceText($variants,'hpp') ?> <button type="button" data-edit-global-hpp data-store="<?= htmlspecialchars($product['store_id'],ENT_QUOTES) ?>" data-product="<?= htmlspecialchars($first['external_product_id'],ENT_QUOTES) ?>" data-sku="<?= htmlspecialchars($first['sku'],ENT_QUOTES) ?>" data-hpp="<?= $first['hpp']??'' ?>" data-variants="<?= htmlspecialchars(json_encode(array_map(static fn($v)=>['sku'=>$v['sku'],'name'=>$v['variant_name'],'hpp'=>$v['hpp']],$variants)),ENT_QUOTES) ?>" class="p-2 text-slate-500 hover:text-orange-600" aria-label="Edit HPP produk <?= htmlspecialchars($product['name'],ENT_QUOTES) ?>"><svg aria-hidden="true" viewBox="0 0 24 24" width="15" height="15" class="inline-block align-middle" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="m16 4 4 4M4 16 16 4a2.83 2.83 0 0 1 4 4L8 20l-5 1 1-5Z"/></svg></button></td><td class="p-3"><?php if ($productSection === 'stok'): ?><?= count(array_filter($variants,static fn($v)=>$v['stock_qty']===null)) ? 'Belum lengkap' : array_sum(array_column($variants,'stock_qty')) ?><?php else: ?><button type="button" data-product-toggle="product-<?= $index ?>" aria-expanded="false" class="text-blue-600"><?= count($variants) ?> varian ⌄</button><?php endif; ?></td><td class="p-3"><?= htmlspecialchars(count($statuses)===1 ? reset($statuses) : 'Beragam') ?></td></tr>
            <?php foreach ($variants as $variant): ?><tr hidden data-product-child="product-<?= $index ?>" class="bg-slate-50 border-t text-[11px]"><td class="p-3 pl-10 text-slate-600">└ <?= htmlspecialchars($variant['variant_name'] ?: $variant['sku']) ?></td><td class="p-3 font-mono"><?= htmlspecialchars($variant['sku']) ?></td><td class="p-3 text-slate-400"><?= htmlspecialchars($product['platform']) ?></td><td class="p-3"><?= $variant['sold'] ?></td><td class="p-3"><?= $variant['price']===null ? 'Belum tersedia' : formatRp($variant['price']) ?><?php if ($variant['original_price']!==null && $variant['original_price']>$variant['price']): ?><del class="block text-slate-400"><?= formatRp($variant['original_price']) ?></del><span class="text-orange-600"><?= round((1-$variant['price']/$variant['original_price'])*100,1) ?>% diskon</span><?php endif; ?></td><td class="p-3"><?= $variant['hpp']===null ? 'Belum diisi' : formatRp($variant['hpp']) ?> <button type="button" data-edit-global-hpp data-store="<?= htmlspecialchars($product['store_id']) ?>" data-sku="<?= htmlspecialchars($variant['sku']) ?>" data-hpp="<?= $variant['hpp'] ?? '' ?>" class="p-2 text-slate-500 hover:text-brand-600" aria-label="Edit HPP SKU <?= htmlspecialchars($variant['sku']) ?>"><svg aria-hidden="true" viewBox="0 0 24 24" width="15" height="15" class="inline-block align-middle" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="m16 4 4 4M4 16 16 4a2.83 2.83 0 0 1 4 4L8 20l-5 1 1-5Z"/></svg></button></td><td class="p-3"><?= $productSection==='stok' ? ($variant['stock_qty'] ?? 'Belum tersedia') : htmlspecialchars($variant['variant_name'] ?: '—') ?></td><td class="p-3"><?= htmlspecialchars($variant['source_status'] ?: 'Belum tersedia') ?></td></tr><?php endforeach; ?>
        <?php endforeach; ?>
        <?php if (!$catalogData['products']): ?><tr><td colspan="8" class="p-12 text-center text-slate-500"><?= !empty($storeProductMode)?'Belum ada produk katalog API yang sesuai filter. Pastikan toko terhubung dan katalog sudah disinkronkan.':'Tidak ada produk pada filter ini. Produk akan muncul dari katalog marketplace, transaksi, atau mapping SKU yang sudah tersimpan.' ?></td></tr><?php endif; ?>
        </tbody></table></div>
    </div>
</section>
